package org.eclipse.rdf4j.queryrender;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.junit.jupiter.api.DynamicTest.dynamicTest;

import java.util.stream.Stream;

import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.QueryParseOptions;
import org.eclipse.rdf4j.query.QueryParseOptions.GraphAlgebraMode;
import org.eclipse.rdf4j.query.parser.ParsedBooleanQuery;
import org.eclipse.rdf4j.query.parser.ParsedDescribeQuery;
import org.eclipse.rdf4j.query.parser.ParsedGraphQuery;
import org.eclipse.rdf4j.query.parser.ParsedQuery;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.eclipse.rdf4j.queryrender.sparql.TupleExprIRRenderer;
import org.junit.jupiter.api.DynamicTest;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestFactory;

class TupleExprIRRendererGraphModeTest {
	private static final QueryParseOptions GRAPH = QueryParseOptions.DEFAULT
			.withGraphAlgebraMode(GraphAlgebraMode.GRAPH);
	private static final QueryParseOptions LEGACY = QueryParseOptions.DEFAULT
			.withGraphAlgebraMode(GraphAlgebraMode.LEGACY);
	private static final String ASK = "ASK WHERE { GRAPH ?g { ?s <urn:p> ?o } }";
	private static final String CONSTRUCT = "CONSTRUCT { ?s <urn:p> ?o } WHERE { GRAPH ?g { ?s <urn:p> ?o } }";
	private static final String DESCRIBE = "DESCRIBE ?s WHERE { GRAPH ?g { ?s <urn:p> ?o } }";

	@Test
	void defaultVerifierPreservesExplicitGraphInAsk() {
		assertRoundTrip(ASK, GRAPH, new TupleExprIRRenderer());
	}

	@TestFactory
	Stream<DynamicTest> defaultVerifierPreservesExplicitGraphInNestedAndGraphQueries() {
		return Stream.of(
				CONSTRUCT,
				DESCRIBE,
				"ASK WHERE { GRAPH ?g {} }",
				"ASK WHERE { FILTER EXISTS { GRAPH ?g { ?s <urn:p> ?o } } }",
				"ASK WHERE { SERVICE <urn:service> { GRAPH ?g { ?s <urn:p> ?o } } }",
				"CONSTRUCT { ?s <urn:p> ?o } WHERE { GRAPH <urn:outer> { GRAPH ?g { ?s <urn:p> ?o } } }",
				"DESCRIBE ?s WHERE { { SELECT ?s WHERE { GRAPH ?g { ?s <urn:p> ?o } } } }")
				.map(query -> dynamicTest(query, () -> assertRoundTrip(query, GRAPH, new TupleExprIRRenderer())));
	}

	@TestFactory
	Stream<DynamicTest> defaultVerifierPreservesLegacyGraph() {
		return Stream.of(ASK, CONSTRUCT, DESCRIBE)
				.map(query -> dynamicTest(query, () -> assertRoundTrip(query, LEGACY, new TupleExprIRRenderer())));
	}

	@Test
	void autoModePreservesBlankNodeSyntaxAndDoesNotModifyConfig() {
		String query = "ASK WHERE { GRAPH <urn:g> { <_:fixed> <urn:p> ?o } }";
		assertRoundTrip(query, GRAPH, new TupleExprIRRenderer());

		TupleExprIRRenderer.Config config = new TupleExprIRRenderer.Config();
		config.parseOptions = QueryParseOptions.STRICT;
		TupleExprIRRenderer renderer = new TupleExprIRRenderer(config);

		assertRoundTrip(ASK, GRAPH.withBlankNodeReferences(false), renderer);
		assertRoundTrip(ASK, LEGACY.withBlankNodeReferences(false), renderer);
		assertThat(config.parseOptions).isSameAs(QueryParseOptions.STRICT);
		assertThatThrownBy(() -> render(renderer, parse(query, GRAPH)))
				.isInstanceOf(IllegalArgumentException.class);
	}

	@Test
	void explicitGraphModeStillControlsVerification() {
		TupleExprIRRenderer.Config config = new TupleExprIRRenderer.Config();
		config.parseOptions = GRAPH;
		assertRoundTrip(ASK, GRAPH, new TupleExprIRRenderer(config));
		assertThatThrownBy(() -> render(new TupleExprIRRenderer(config), parse(ASK, LEGACY)))
				.isInstanceOf(IllegalStateException.class)
				.hasMessageStartingWith("Rendered SPARQL does not round-trip to the original TupleExpr.");

		config.parseOptions = LEGACY;
		assertRoundTrip(ASK, LEGACY, new TupleExprIRRenderer(config));
		assertThatThrownBy(() -> render(new TupleExprIRRenderer(config), parse(ASK, GRAPH)))
				.isInstanceOf(IllegalStateException.class)
				.hasMessageStartingWith("Rendered SPARQL does not round-trip to the original TupleExpr.");
	}

	private static void assertRoundTrip(String query, QueryParseOptions options, TupleExprIRRenderer renderer) {
		ParsedQuery original = parse(query, options);
		String rendered = render(renderer, original);
		ParsedQuery reparsed = parse(rendered, options);
		assertThat(VarNameNormalizer.normalizeModelVariables(reparsed.getTupleExpr()))
				.isEqualTo(VarNameNormalizer.normalizeModelVariables(original.getTupleExpr()));
	}

	private static ParsedQuery parse(String query, QueryParseOptions options) {
		return QueryParserUtil.parseQuery(QueryLanguage.SPARQL, query, null, options);
	}

	private static String render(TupleExprIRRenderer renderer, ParsedQuery parsed) {
		return switch (parsed) {
		case ParsedBooleanQuery ask -> renderer.renderAsk(ask.getTupleExpr(), null);
		case ParsedDescribeQuery describe -> renderer.renderDescribe(describe.getTupleExpr(), null);
		case ParsedGraphQuery construct -> renderer.renderConstruct(construct.getTupleExpr(), null);
		default -> throw new AssertionError("Unexpected query form: " + parsed.getClass());
		};
	}
}
